/**
 * @file project/app/api/parsers/board.fixture-mixed-width.test.js
 * Plain Node `assert` test (E86_S06_T04) that drives `parseBoard()` from the shared mixed-width board fixture
 * generated by `tests/helpers/mixed-width-board.sh` (E86_S06_T01), instead of from inline data like
 * `board.mixed-width.test.js` and `board.numeric-order.test.js` do.
 *
 * The generator is called through `child_process` into a temporary directory, `JENGA_PROJECT_ROOT` is pointed
 * at it before `board.js` is first required (its root is fixed at module load), and the parsed tree is asserted:
 *   - epics list E01, E10, E11, E99, E100, E101, E1001 in that numeric order;
 *   - each epic holds only its own stories and each story only its own tasks (no E100 story under E10, no
 *     E1001 story under E100), with stories and tasks in numeric order (S1 before S10, T99 before T100);
 *   - `_queued` is set on exactly the IDs the fixture's `project/todo.md` lists, wide ones included;
 *   - the generator's `--two-digit` board still parses to its own epics, stories and tasks in order.
 *
 * Skips cleanly (exit 0, with a message) when `bash` or the generator is unavailable. Writes only inside a
 * temporary directory, removed on exit.
 *
 * Run directly:
 *   node project/app/api/parsers/board.fixture-mixed-width.test.js
 * or, from project/app/api/:
 *   npm test
 */

'use strict';

const assert = require('assert');
const fs = require('fs');
const os = require('os');
const path = require('path');
const { spawnSync } = require('child_process');

const GENERATOR = path.resolve(__dirname, '../../../../tests/helpers/mixed-width-board.sh');

function skip(why) {
  console.log(`SKIP board.fixture-mixed-width: ${why}`);
  process.exit(0);
}

if (!fs.existsSync(GENERATOR)) skip(`generator not found at ${GENERATOR}`);
if (spawnSync('bash', ['--version'], { encoding: 'utf8' }).status !== 0) skip('bash is not available');

const TMP = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'board-fixture-mixed-width-')));
process.on('exit', () => fs.rmSync(TMP, { recursive: true, force: true }));

function generate(dir, ...flags) {
  const r = spawnSync('bash', [GENERATOR, dir, ...flags], { encoding: 'utf8' });
  if (r.status !== 0) skip(`generator exited ${r.status}: ${(r.stderr || r.error || '').toString().trim()}`);
}

const WIDE = path.join(TMP, 'wide');
const NARROW = path.join(TMP, 'two-digit');
generate(WIDE);
generate(NARROW, '--two-digit');

// The wide root is set before board.js is first required; the two-digit board is parsed in a child process.
process.env.JENGA_PROJECT_ROOT = WIDE;
const { parseBoard } = require('./board');

// id of every story and task, as the generator writes it (see its header). Stories S01 and S1 are the same
// number, so the tie breaks by text: S01 then S1.
const WIDE_TREE = {
  E01: { E01_S01: ['E01_S01_T01', 'E01_S01_T02'] },
  E10: { E10_S01: ['E10_S01_T01'], E10_S1: ['E10_S1_T1'], E10_S10: ['E10_S10_T10'] },
  E11: { E11_S01: ['E11_S01_T01'] },
  E99: { E99_S99: ['E99_S99_T99'] },
  E100: { E100_S10: ['E100_S10_T10'], E100_S100: ['E100_S100_T99', 'E100_S100_T100'] },
  E101: { E101_S01: ['E101_S01_T01'] },
  E1001: { E1001_S01: ['E1001_S01_T01'], E1001_S100: ['E1001_S100_T100'] },
};
const NARROW_TREE = {
  E01: { E01_S01: ['E01_S01_T01', 'E01_S01_T02'] },
  E10: { E10_S01: ['E10_S01_T01'], E10_S10: ['E10_S10_T10'] },
  E11: { E11_S01: ['E11_S01_T01'] },
  E99: { E99_S99: ['E99_S99_T99'] },
};

function shape(board) {
  return board.map((e) => [e.id, e.stories.map((s) => [s.id, s.tasks.map((t) => t.id)])]);
}
function expectedShape(tree) {
  return Object.entries(tree).map(([e, stories]) => [e, Object.entries(stories)]);
}
function queuedIds(board) {
  const ids = [];
  for (const e of board) {
    if (e._queued) ids.push(e.id);
    for (const s of e.stories) {
      if (s._queued) ids.push(s.id);
      for (const t of s.tasks) if (t._queued) ids.push(t.id);
    }
  }
  return ids.sort();
}

(async () => {
  const board = await parseBoard();

  // --- Order and grouping -------------------------------------------------------------------------------------
  assert.deepStrictEqual(board.map((e) => e.id), ['E01', 'E10', 'E11', 'E99', 'E100', 'E101', 'E1001'], 'epic order');
  assert.deepStrictEqual(shape(board), expectedShape(WIDE_TREE), 'every epic holds exactly its own stories, tasks in numeric order');
  for (const epic of board) {
    for (const story of epic.stories) {
      assert.strictEqual(story.epic_id, epic.id, `${story.id} is listed under ${epic.id}`);
      for (const task of story.tasks) assert.strictEqual(task.story_id, story.id, `${task.id} is listed under ${story.id}`);
    }
  }
  const e100 = board.find((e) => e.id === 'E100');
  assert.deepStrictEqual(
    e100.stories.find((s) => s.id === 'E100_S100').tasks.map((t) => t.id),
    ['E100_S100_T99', 'E100_S100_T100'],
    'T99 before T100 (numeric, not text, order)'
  );
  assert.ok(!board.find((e) => e.id === 'E10').stories.some((s) => /^E10\d/.test(s.id)), 'no E100 or E1001 story under E10');

  // --- Todo-queue flagging: exactly the IDs the fixture's todo.md lists -----------------------------------------
  const todo = fs.readFileSync(path.join(WIDE, 'project/todo.md'), 'utf8');
  const listed = todo.split('\n').filter((l) => !l.startsWith('<!--')).map((l) => l.split(': ').pop().trim()).filter((v) => /^E\d+(_S\d+)?(_T\d+)?$/.test(v));
  assert.ok(listed.includes('E1001_S100_T100') && listed.includes('E100_S100_T100'), 'fixture todo.md lists wide IDs');
  assert.deepStrictEqual(queuedIds(board), listed.slice().sort(), '_queued is set on exactly the IDs listed in todo.md');
  const t100 = e100.stories.find((s) => s.id === 'E100_S100').tasks;
  assert.strictEqual(t100.find((t) => t.id === 'E100_S100_T100')._queued, true, 'wide task listed in todo.md is queued');
  assert.strictEqual(t100.find((t) => t.id === 'E100_S100_T99')._queued, undefined, 'a RECONCILED comment queues nothing');
  assert.strictEqual(e100._queued, undefined, 'a wide task in the queue does not queue its epic');

  // --- The two-digit board is untouched by the wide-ID handling -----------------------------------------------
  const child = spawnSync(process.execPath, ['-e', 'require("./parsers/board").parseBoard().then((b) => console.log(JSON.stringify(b.map((e) => [e.id, e.stories.map((s) => [s.id, s.tasks.map((t) => t.id)])]))))'], {
    cwd: path.resolve(__dirname, '..'), env: { ...process.env, JENGA_PROJECT_ROOT: NARROW }, encoding: 'utf8',
  });
  assert.strictEqual(child.status, 0, `two-digit parse failed: ${child.stderr}`);
  const narrow = JSON.parse(child.stdout);
  assert.deepStrictEqual(narrow, expectedShape(NARROW_TREE), 'two-digit epics, stories and tasks, in order');
  assert.ok(JSON.stringify(narrow).match(/E\d+(_S\d+)?(_T\d+)?/g).every((id) => id.split('_').every((p) => p.length <= 3)), 'two-digit board has no wide ID');

  console.log('board.fixture-mixed-width: all assertions passed');
})().catch((err) => {
  console.error(err);
  process.exit(1);
});
